INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(38611, 'Job 20:10', 'Job', 20, 10, 'د هغوئ د اولاد نه به هغه مال دولت واپس لاړ شى، چې کوم يې د غريبانانو نه اخستے وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_10.mp3', '', 1761754199, 1761754199),
(38612, 'Job 20:11', 'Job', 20, 11, 'هغوئ به په ځوانۍ کښې مړۀ شى او په خاورو کښې به ښخ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_11.mp3', '', 1761754199, 1761754199),
(38613, 'Job 20:12', 'Job', 20, 12, 'په بدعملۍ کښې خوند وى، او د دې خوند تر ډېر وخته پورې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_12.mp3', '', 1761754199, 1761754199),
(38614, 'Job 20:13', 'Job', 20, 13, 'او د خوږ څيز په شان يې په خولۀ کښې د ډېر وخت پورې ساتى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_13.mp3', '', 1761754199, 1761754199),
(38615, 'Job 20:14', 'Job', 20, 14, 'خو ناګهانه د هغوئ خوراک په خېټه کښې تريخ شى، او د دې نه دننه زهر جوړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_14.mp3', '', 1761754199, 1761754199),
(38616, 'Job 20:15', 'Job', 20, 15, 'هغوئ مال دولت تېر کړى خو بيا يې اولټۍ کړى، خُدائ پاک د هغوئ دولت د هغوئ د خېټې نه واپس راوغورزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_15.mp3', '', 1761754199, 1761754199),
(38617, 'Job 20:16', 'Job', 20, 16, 'هغوئ به د مارانو زهر وخورى، او زهرژن مار به هغوئ ووژنى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_16.mp3', '', 1761754199, 1761754199),
(38618, 'Job 20:17', 'Job', 20, 17, 'هغوئ به سيندونه ونۀ ګورى، هغه نِهرونه چې شات او پئ په کښې بهيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_17.mp3', '', 1761754199, 1761754199),
(38619, 'Job 20:18', 'Job', 20, 18, 'د هغوئ ناجائزه ګټه به د هغوئ نه واپس وځى، او په مال دولت باندې به خوشحالى ونۀ کړى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_18.mp3', '', 1761754199, 1761754199),
(38620, 'Job 20:19', 'Job', 20, 19, 'ځکه چې هغوئ غريبانان وهلى دى او نهر يې پرېښى دى، او د هغوئ کورونه يې قبضه کړى دى کوم چې هغوئ نۀ دى جوړ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_19.mp3', '', 1761754199, 1761754199),
(38621, 'Job 20:20', 'Job', 20, 20, 'د هغوئ د حرص ختمېدل نشته، چې په څۀ خوشحاليږى نو د هغې نه به ورسره هيڅ پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_20.mp3', '', 1761754199, 1761754199),
(38622, 'Job 20:21', 'Job', 20, 21, 'هغوئ چې څۀ خورى نو د هغې نه هيڅ نۀ پاتې کيږى، نو په دې وجه د هغوئ مالدارى ختميږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_21.mp3', '', 1761754199, 1761754199),
(38623, 'Job 20:22', 'Job', 20, 22, 'کله چې هغوئ ښۀ کامياب وى، نو د غم چپې به په هغوئ باندې راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_22.mp3', '', 1761754199, 1761754199),
(38624, 'Job 20:23', 'Job', 20, 23, 'چې کله هغوئ خپلې خېټې ډکې کړى نو خُدائ پاک دې په هغوئ باندې سخت قهر راولى، او دا قهر دې په هغوئ لکه د ږلۍ راوريږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_23.mp3', '', 1761754199, 1761754199),
(38625, 'Job 20:24', 'Job', 20, 24, 'هغوئ به د اوسپنې د وسلې نه تښتى، خو د زېړو په غشى به هغوئ ولګى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_24.mp3', '', 1761754199, 1761754199),
(38626, 'Job 20:25', 'Job', 20, 25, 'هغه غشے د هغوئ د ملا نه وويستلے شى، او دا غشے په وينه سور وى، يره به په هغوئ باندې راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_25.mp3', '', 1761754199, 1761754199),
(38627, 'Job 20:26', 'Job', 20, 26, 'د هغوئ خزانه به په تکه توره تيارۀ کښې پټه شى، يو داسې اور به هغوئ تباه کړى چې هيچا بل کړے نۀ وى، او د هغوئ په کور کښې پاتې هر څۀ به تباه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_26.mp3', '', 1761754199, 1761754199),
(38628, 'Job 20:27', 'Job', 20, 27, 'آسمانونه به د هغوئ ګناه ښکاره کړى، او زمکه به د هغوئ خِلاف ګواهى ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_27.mp3', '', 1761754199, 1761754199),
(38629, 'Job 20:28', 'Job', 20, 28, 'يو سېلاب به د هغۀ کور يوسى، د خُدائ پاک قهر به په هغوئ سېلاب راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_28.mp3', '', 1761754199, 1761754199),
(38630, 'Job 20:29', 'Job', 20, 29, 'دا د خُدائ پاک د طرف نه د بدعمله کسانو اَنجام دے، دا د هغوئ هغه ميراث دے چې د خُدائ پاک د طرف نه يې فېصله شوې ده.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job20_verse_29.mp3', '', 1761754199, 1761754199),
(38631, 'Isaiah 45:1', 'Isaiah', 45, 1, 'څښتن ټاکلی دی کوروش چې شي پاچا او زور او واک یې دی ورکړی ورته چې قومونه یې تابع شي چې کړي لېرې پاچاهان له واکه څښتن به خلاصې دروازې کړي د ښار د هغه دپاره او نورې به نه بندیږي څښتن کوروش ته داسې وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_1.mp3', '', 1761754199, 1761754199),
(38632, 'Isaiah 45:2', 'Isaiah', 45, 2, '«زه به په خپله ځمه ستا نه مخکې او هوار به کړمه غرونه زه به برنجي دروازې ماتې کړمه او اړمونه به یې د اوسپنې ټوټې ټوټې کړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_2.mp3', '', 1761754199, 1761754199),
(38633, 'Isaiah 45:3', 'Isaiah', 45, 3, 'زه به تاته خزانې درکړم د تورو تیارو ځایونو او هم به درکړم شتمني تاته د پټو ځایونو بیا به ته پوه شې چې زه څښتن د اسراییلو خدای یم څوک چې تاته کړي په نوم اواز', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_3.mp3', '', 1761754199, 1761754199),
(38634, 'Isaiah 45:4', 'Isaiah', 45, 4, 'ته مې ټاکلی یې ترڅو مرسته وکړې زما د خدمتګار یعقوب او مرسته وکړې زما د غوره شوي قوم اسراییلو سره سره له دې چې ته ما نه پېژنې زه په نوم اواز کومه تاته او درکوم لقب د عزت تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_4.mp3', '', 1761754199, 1761754199),
(38635, 'Isaiah 45:5', 'Isaiah', 45, 5, 'زه څښتن یم، نشته بل خدای پرته له ما سره له دې چې ته ما نه پېژنې زه به تاته درکړم توان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_5.mp3', '', 1761754199, 1761754199),
(38636, 'Isaiah 45:6', 'Isaiah', 45, 6, 'د دې دپاره زه کوم دا کار چې له ختیځه تر لوېدیځه پورې ټول خلک پوه شي په دې چې زه څښتن یم او بل خدای نشته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_6.mp3', '', 1761754199, 1761754199),
(38637, 'Isaiah 45:7', 'Isaiah', 45, 7, 'زه خالق یم د تیارې او رڼا زه راولمه مصیبت او سوله زه څښتن یم او کوم دا ټول کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_7.mp3', '', 1761754199, 1761754199),
(38638, 'Isaiah 45:8', 'Isaiah', 45, 8, 'ای اسمانه، ای ورېځو راووروه ته عدالت لکه باران په شان ځمکه دې پرانیستل شي ترڅو خلاصون او عدالت راشين شي او په کې وغوړیږي د عدالت او د خلاصون غوټۍ زه څښتن کوم دا ټول کارونه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_8.mp3', '', 1761754199, 1761754199),
(38639, 'Isaiah 45:9', 'Isaiah', 45, 9, 'افسوس په حال د هغه چې کړي جګړه د خپل خالق سره هغه داسې دی لکه منګی چې د کلال سره کوي جګړه ایا خټه کولای شي وکړي پوښتنه د کلال څخه دا چې ته څه جوړوې؟ یا خټه ووایي کلال ته چې ته مهارت نه لرې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_9.mp3', '', 1761754199, 1761754199),
(38640, 'Isaiah 45:10', 'Isaiah', 45, 10, 'افسوس په حال د هغه چا چې ووایي خپل مور او پلار ته: «تاسو ولې په دې شکل زېږولی یمه؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_10.mp3', '', 1761754199, 1761754199),
(38641, 'Isaiah 45:11', 'Isaiah', 45, 11, 'څښتن، سپېڅلی خدای د اسراییلو او خالق د هغوی داسې وایي: «تاسو کولای شئ پوښتنه وکړئ ما نه راتلونکي وخت په هکله خو حق نه لرئ چې پوښتنه وکړئ ما نه زما د اولادو په اړه او یا راته ووایئ چې باید څه وکړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_11.mp3', '', 1761754199, 1761754199),
(38642, 'Isaiah 45:12', 'Isaiah', 45, 12, 'زه هغه ذات یم چې مې جوړه کړله ځمکه او انسان مې خلق کړ چې په کې واوسیږي اسمانونه مې خپاره کړل په خپل لاس لمر، سپوږمۍ او ستوري دي زما فرمان کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_12.mp3', '', 1761754199, 1761754199),
(38643, 'Isaiah 45:13', 'Isaiah', 45, 13, 'ما په خپله هڅولی دی کوروش چې وکړي سم او د عدالت کارونه په کومو لارو چې سفر کړي هغه هغه به سمې کړمه هغه به بېرته زما ښار اورشلیم ودان کړي او زما خلک به ازاد له اسارت کړي دا کار به وکړي کوروش په وړیا توګه نه به پیسې واخلي او نه به سوغات» داسې وایي مطلق قادر څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_13.mp3', '', 1761754199, 1761754199),
(38644, 'Isaiah 45:14', 'Isaiah', 45, 14, 'څښتن اسراییلو ته داسې وایي: «مال او شتمني د مصر او ایتوپیا به وي د ستاسو او د سیبا لوړ قدي خلک به غلامان وي ستاسو په زنځیرونو کې روان به وي هغوی تاسو پسې تاسو ته ټیټ به خپل سرونه کړي او اقرار به وکړي چې څښتن مل دی یوازې تاسو سره نشته بل خدای پرته له هغه نه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_14.mp3', '', 1761754199, 1761754199),
(38645, 'Isaiah 45:15', 'Isaiah', 45, 15, 'ای د اسراییلو خدایه او ای ژغورونکیه په رښتیا ته هغه خدای یې چې خپل ځان پټوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_15.mp3', '', 1761754199, 1761754199),
(38646, 'Isaiah 45:16', 'Isaiah', 45, 16, 'څوک چې بتان جوړوي ټول به وشرمیږي او شي به رسوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_16.mp3', '', 1761754199, 1761754199),
(38647, 'Isaiah 45:17', 'Isaiah', 45, 17, 'خو څښتن به اسراییل وژغوري او خلاصون به یې پایښت ومومي د تل دپاره د رسوایۍ سره به مخ نه شي د هغه قوم هېڅکله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_17.mp3', '', 1761754199, 1761754199),
(38648, 'Isaiah 45:18', 'Isaiah', 45, 18, 'څښتن هغه خدای دی چې یې جوړ کړل اسمانونه هغه جوړه کړله ځمکه، هغه یې کړه ټینګه او کلکه جوړه یې نه کړله خالي هغه هغه یې جوړه کړه د دې دپاره چې په کې واوسیږي خلک دا هغه ذات دی چې داسې وایي: «زه یم څښتن او نشته بل خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_18.mp3', '', 1761754199, 1761754199),
(38649, 'Isaiah 45:19', 'Isaiah', 45, 19, 'ما نه دي کړې پټې خبرې پټ مې ساتلی نه دی خپل مقصد د یعقوب اولادې ته مې ویلي نه دي چې ما لټوئ بېځایه زه څښتن یم او رښتیا وایم او اعلانوم زه حق»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_19.mp3', '', 1761754199, 1761754199),
(38650, 'Isaiah 45:20', 'Isaiah', 45, 20, 'څښتن وایي: «ای له قومونو پاتې شویو ژوندي خلکو شئ راټول او راشئ زما حضور ته! چې ګرځوي څوک د لرګیو بتان د خپل ځانه سره دعا کوي هغو خدایانو ته چې دوی ژغورلی نه شي هغوی جاهل دي او په هېڅ نه پوهیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_20.mp3', '', 1761754199, 1761754199),
(38651, 'Isaiah 45:21', 'Isaiah', 45, 21, 'راشئ او خپله دعوه وړاندې کړئ په محکمه کې خلک پرېږدئ چې مشوره وکړي یو د بله سره چا وه کړې پېشګویي له ډېر پخوا نه چې څه به کیږي؟ ایا هغه څښتن زه نه وم؟ زه ژغورونکی او عادل خدای یم زما نه پرته بل خدای نشته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_21.mp3', '', 1761754199, 1761754199),
(38652, 'Isaiah 45:22', 'Isaiah', 45, 22, 'ای د ټولې نړۍ خلکو راستانه شئ ماته ترڅو وژغورل شئ ځکه چې زه یوازېنی خدای یم او زما نه پرته بل خدای نشته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_22.mp3', '', 1761754199, 1761754199),
(38653, 'Isaiah 45:23', 'Isaiah', 45, 23, 'ما په خپل ذات باندې قسم خوړلی زما وعده ده رښتیا او د باور وړ ده او تل هغې ته وفادار یم هر یو راځي به او په ګونډو به شي زما په مخکې او هره ژبه به قسم خوري زما په نوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_23.mp3', '', 1761754199, 1761754199),
(38654, 'Isaiah 45:24', 'Isaiah', 45, 24, 'خلک به وایي چې بری او توان یوازې څښتن پورې اړه لري هرڅوک چې په قهر دي په ما باندې هغوی به راشي زما حضور ته او هغوی به وشرمیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_24.mp3', '', 1761754199, 1761754199),
(38655, 'Isaiah 45:25', 'Isaiah', 45, 25, 'بریالی به شي ټول قوم د اسراییلو د څښتن په وسیله او خوشحالي به هغوی وکړي د هغه په خاطر»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah45_verse_25.mp3', '', 1761754199, 1761754199),
(38656, 'Ruth 2:1', 'Ruth', 2, 1, 'نعومي یو شتمن او مهم خپلوان درلود چې بوعز نومېده چې د هغې د مېړه الیملک د کورنۍ څخه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_1.mp3', '', 1761754199, 1761754199),
(38657, 'Ruth 2:2', 'Ruth', 2, 2, 'یوه ورځ روت نعومي ته وویل: «که ستا خوښه وي زه به پټیو ته لاړه شم او هغه وږي به راټول کړم چې د لوګرو څخه پاتې شوي دي. زه باور لرم داسې یو څوک به پیدا کړم چې ماته د دې کار د کولو اجازه راکړي.» نعومي ځواب ورکړ: «ځه لورې لاړه شه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_2.mp3', '', 1761754199, 1761754199),
(38658, 'Ruth 2:3', 'Ruth', 2, 3, 'نو روت پټیو ته لاړه، د لوګرو پسې روانه شوه او هغه وږي یې راټولول چې د دوی څخه به پاتې کېدل. په هغو پټیو کې چې هغې کار کاوه، هغه د بوعز وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_3.mp3', '', 1761754199, 1761754199),
(38659, 'Ruth 2:4', 'Ruth', 2, 4, 'څه وخت وروسته بوعز په خپله د بیت لحم نه راغی او لوګرو ته یې وویل: «څښتن مو مل شه!» هغوی ورته په ځواب کې وویل: «څښتن دې تاته برکت درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_4.mp3', '', 1761754199, 1761754199),
(38660, 'Ruth 2:5', 'Ruth', 2, 5, 'بوعز د لوګرو د مشر څخه پوښتنه وکړه: «هغه ځوانه ښځه څوک ده؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_5.mp3', '', 1761754199, 1761754199),
(38661, 'Ruth 2:6', 'Ruth', 2, 6, 'سړي په ځواب کې وویل: «دا هغه موآبۍ ښځه ده چې د نعومي سره د موآب نه راغلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_6.mp3', '', 1761754199, 1761754199),
(38662, 'Ruth 2:7', 'Ruth', 2, 7, 'هغې زما څخه اجازه وغوښتله چې لاړه شي او هغه وږي راټول کړي چې د لوګرو څخه پاتې کیږي. هغه د سهار وختي نه تر اوسه پورې کار کوي او همدا اوس یې کار بس کړ چې د جونګړې لاندې لږ ارام وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_7.mp3', '', 1761754199, 1761754199),
(38663, 'Ruth 2:8', 'Ruth', 2, 8, 'نو بیا بوعز روت ته ورغی او ویې ویل: «زه فکر کوم تاته به دا ډېره ښه وي چې د بل چا په پټیو کې وږي راټول نه کړې. ته همدلته د ښځو سره پاتې شه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_8.mp3', '', 1761754199, 1761754199),
(38664, 'Ruth 2:9', 'Ruth', 2, 9, 'او زما په پټیو کې د لوګرو پسې وږي راټول کړه. ما سړیو ته امر کړی چې تا ونه ځوروي او هرکله چې تږې کېږې، د هغو منګیو څخه اوبه څښلی شې چې هغوی ډک کړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_9.mp3', '', 1761754199, 1761754199),
(38665, 'Ruth 2:10', 'Ruth', 2, 10, 'روت د درناوي په خاطر ټیټه شوه او ویې ویل: «ته پوهېږې چې زه د بل هېواد څخه راغلې یم. ته ولې زما سره دومره نېکي کوې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_10.mp3', '', 1761754199, 1761754199),
(38666, 'Ruth 2:11', 'Ruth', 2, 11, 'بوعز په ځواب کې وویل: «ما د ټولو هغو شیانو په هکله اورېدلي دي چې تا د خپلې خواښې دپاره د خپل مېړه د مرګ څخه وروسته تر سره کړي دي. زه پوهېږم چې څنګه تا خپله مور او پلار او خپل هېواد پرېښود او څنګه راغلې، ترڅو د داسې خلکو په منځ کې واوسېږې چې تا پخوا هېڅ نه پېژندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_11.mp3', '', 1761754199, 1761754199),
(38667, 'Ruth 2:12', 'Ruth', 2, 12, 'زه دعا کوم چې څښتن دې د دې کار دپاره تاته اجر درکړي. د اسراییلو څښتن خدای چې تا ورته پناه وروړې ده، د دې کار پوره اجر درکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_12.mp3', '', 1761754199, 1761754199),
(38668, 'Ruth 2:13', 'Ruth', 2, 13, 'روت په ځواب کې وویل: «باداره، دا ستا ډېره نېکي ده چې ته په ډېرې مهربانۍ سره زما سره خبرې کوې او زما هرکلی کوې، زه حتی ستا د یوې وینځې برابره هم نه یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_13.mp3', '', 1761754199, 1761754199),
(38669, 'Ruth 2:14', 'Ruth', 2, 14, 'د ډوډۍ خوړلو په وخت کې بوعز روت ته وویل: «راځه مونږ سره ډوډۍ وخوره. لږه ډوډۍ واخله او په سرکه کې یې لمده کړه.» هغه د لوګرو سره کښېناستله او بوعز هغې ته وریتې شوې غلې دانې ورکړې، روت چې څومره غوښتل ویې خوړې او لږې ورڅخه پاتې هم شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_14.mp3', '', 1761754199, 1761754199),
(38670, 'Ruth 2:15', 'Ruth', 2, 15, 'وروسته د هغې چې روت د وږو د راټولولو دپاره لاړه، بوعز خپلو سړیو ته وویل: «هغه پرېږدئ چې د ګېډیو څخه هم وږي واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_15.mp3', '', 1761754199, 1761754199),
(38671, 'Ruth 2:16', 'Ruth', 2, 16, 'د ګېډیو څخه هم یو څه وږي راوباسئ او ورته یې پرېږدئ او د هغې سره سختې خبرې مه کوئ!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_16.mp3', '', 1761754199, 1761754199),
(38672, 'Ruth 2:17', 'Ruth', 2, 17, 'نو روت په پټیو کې تر ماښامه پورې کار وکړ. کله چې هغې ټول وږي وټکول، نو هغه لس کیلو ګرامه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_17.mp3', '', 1761754199, 1761754199),
(38673, 'Ruth 2:18', 'Ruth', 2, 18, 'هغې دا وږي ښار ته یووړل او خپلې خواښې ته یې وروښودل چې څومره یې راټول کړي وو. روت هغه ډوډۍ هم ورته ورکړه چې د غرمې نه پاتې شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_18.mp3', '', 1761754199, 1761754199),
(38674, 'Ruth 2:19', 'Ruth', 2, 19, 'نعومي وویل: «تا نن چېرته او د چا په پټیو کې کار وکړ؟ خدای دې هغه سړي ته برکت ورکړي چې ستا سره یې ډېر ښه چلند وکړ!» بیا روت هغې ته وویل: «ما د یو سړي په پټیو کې کار وکړ چې بوعز نومېده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_19.mp3', '', 1761754199, 1761754199),
(38675, 'Ruth 2:20', 'Ruth', 2, 20, 'نعومي په ځواب کې وویل: «څښتن دې بوعز ته برکت ورکړي! څښتن تل د مړو او ژوندیو سره وفادار دی.» نعومي زیاته کړه: «بوعز زمونږ د هغو نژدې خپلوانو د ډلې څخه دی چې زمونږ ساتنه کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_20.mp3', '', 1761754199, 1761754199),
(38676, 'Ruth 2:21', 'Ruth', 2, 21, 'روت هغې ته وویل: «بوعز حتی ماته وویل چې د لو تر خلاصېدلو پورې زما د لوګرو سره وږي راټولوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_21.mp3', '', 1761754199, 1761754199),
(38677, 'Ruth 2:22', 'Ruth', 2, 22, 'نعومي په ځواب کې وویل: «زما لورې دا ښه خبره ده چې ته د هغو ښځو سره وږي راټول کړې چې د بوعز په پټیو کې کار کوي، ځکه کېدای شي د بل چا په پټیو کې ستا سره بد چلند وشي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_22.mp3', '', 1761754199, 1761754199),
(38678, 'Ruth 2:23', 'Ruth', 2, 23, 'نو بیا روت د کار کولو په وخت کې نورو ښځو سره نژدې اوسېدله. روت تر هغه وخته پورې په پټیو کې کار کاوه، ترڅو چې ټولې اوربشې او غنم ورېبل شول. په دې ټوله موده کې هغه د خپلې خواښې سره اوسېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ruth2_verse_23.mp3', '', 1761754199, 1761754199),
(38679, 'Genesis 25:1', 'Genesis', 25, 1, 'ابراهیم بله ښځه وکړه چې نوم یې قطوره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_1.mp3', '', 1761754199, 1761754199),
(38680, 'Genesis 25:2', 'Genesis', 25, 2, 'د هغې څخه د ابراهیم زامن زمران، یقشان، مدان، مدیان، یشباق او شوحا پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_2.mp3', '', 1761754199, 1761754199),
(38681, 'Genesis 25:3', 'Genesis', 25, 3, 'یقشان د شیبا او ددان پلار ؤ او آشوریم، لطوشیم او لیومیم د ددان اولاده وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_3.mp3', '', 1761754199, 1761754199),
(38682, 'Genesis 25:4', 'Genesis', 25, 4, 'عیفه، عیفر، حنوک، ابیداع او الداعه د مدیان زامن وو. دا ټول د قطورې اولاده وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_4.mp3', '', 1761754199, 1761754199),
(38683, 'Genesis 25:5', 'Genesis', 25, 5, 'ابراهیم خپله ټوله شتمني اسحاق ته پرېښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_5.mp3', '', 1761754199, 1761754199),
(38684, 'Genesis 25:6', 'Genesis', 25, 6, 'خو هغه لا ژوندی ؤ چې د خپلو وینځو زامنو ته یې سوغاتونه ورکړل او هغوی یې د خپل زوی اسحاق څخه د ختیځ خواته لېرې ولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_6.mp3', '', 1761754199, 1761754199),
(38685, 'Genesis 25:7', 'Genesis', 25, 7, 'ابراهیم پوره یوسلو پنځه اویا کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_7.mp3', '', 1761754199, 1761754199),
(38686, 'Genesis 25:8', 'Genesis', 25, 8, 'هغه په پاخه عمر کې مړ شو او د خپلو نیکونو سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_8.mp3', '', 1761754199, 1761754199),
(38687, 'Genesis 25:9', 'Genesis', 25, 9, 'د هغه زامنو اسحاق او اسماعیل هغه ممري ته نژدې د حیتي صوحار د زوی عفرون په پټي کې د مکفیله په سمڅه کې ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_9.mp3', '', 1761754199, 1761754199),
(38688, 'Genesis 25:10', 'Genesis', 25, 10, 'دا هغه پټی ؤ چې ابراهیم د حیتیانو څخه په بیه اخیستی ؤ. ابراهیم او د هغه ښځه ساره دواړه په هغه کې ښخ کړای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_10.mp3', '', 1761754199, 1761754199),
(38689, 'Genesis 25:11', 'Genesis', 25, 11, 'د ابراهیم د مرګ څخه وروسته خدای د هغه زوی اسحاق ته برکت ورکړ او اسحاق بئرلحي ریي ته نژدې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_11.mp3', '', 1761754199, 1761754199),
(38690, 'Genesis 25:12', 'Genesis', 25, 12, 'دا د ابراهیم د زوی اسماعیل اولاده ده. دا هغه اسماعیل ؤ چې د ساره د مصرۍ وینځې هاجرې څخه پیدا شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_12.mp3', '', 1761754199, 1761754199),
(38691, 'Genesis 25:13', 'Genesis', 25, 13, 'د اسماعیل د زامنو نومونه د هغوی د زېږېدلو د ترتیب له مخې چې په لست کې لیکل شوي دي دا دي: د اسماعیل مشر زوی نبایوت، قیدار، ادبیل، مبسام،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_13.mp3', '', 1761754199, 1761754199),
(38692, 'Genesis 25:14', 'Genesis', 25, 14, 'مشماع، دومه، مسا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_14.mp3', '', 1761754199, 1761754199),
(38693, 'Genesis 25:15', 'Genesis', 25, 15, 'حداد، تیما، یطور، نافیش او قدمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_15.mp3', '', 1761754199, 1761754199),
(38694, 'Genesis 25:16', 'Genesis', 25, 16, 'دا د اسماعیل زامن وو او دا د دولسو قبیلو د مشرانو نومونه وو چې د هغوی د کلیو او کمپونو له مخې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_16.mp3', '', 1761754199, 1761754199),
(38695, 'Genesis 25:17', 'Genesis', 25, 17, 'اسماعیل پوره د یوسلو اووه دېرشو کالو په عمر مړ شو او د خپلو نیکونو سره یوځای شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_17.mp3', '', 1761754199, 1761754199),
(38696, 'Genesis 25:18', 'Genesis', 25, 18, 'د هغه اولاده د شور او حویلې ترمنځ سیمه کې اوسېدله چې د مصر پولې ته نژدې د آشور په لاره پرته ده. هغوی د خپلو ټولو ورونو سره په دښمنۍ کې ژوند کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_18.mp3', '', 1761754199, 1761754199),
(38697, 'Genesis 25:19', 'Genesis', 25, 19, 'دا د ابراهیم د زوی اسحاق اولاده ده: د ابراهیم څخه اسحاق پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_19.mp3', '', 1761754199, 1761754199),
(38698, 'Genesis 25:20', 'Genesis', 25, 20, 'اسحاق د څلوېښتو کالو په عمر ؤ چې د ربکا سره یې واده وکړ. هغه د آرامي بتوییل چې د بین‌النهرین څخه ؤ، لور او د لابان خور وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_20.mp3', '', 1761754199, 1761754199),
(38699, 'Genesis 25:21', 'Genesis', 25, 21, 'اسحاق د خپلې ښځې په خاطر چې شنډه وه، څښتن ته دعا وکړه. څښتن د هغه دعا قبوله کړه او د هغه ښځه ربکا امیدواره شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_21.mp3', '', 1761754199, 1761754199),
(38700, 'Genesis 25:22', 'Genesis', 25, 22, 'مخکې له دې چې ربکا اولاد وزېږوي، هغه پوه شوه چې هغه به غبرګوني وزېږوي، ځکه چې هغې دا احساس کړه چې هغوی د مور په نس کې یو د بل سره جګړه کوي. هغې وویل: «زما سره ولې داسې کیږي؟» نو هغې د څښتن څخه پوښتنه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_22.mp3', '', 1761754199, 1761754199),
(38701, 'Genesis 25:23', 'Genesis', 25, 23, 'څښتن هغې ته وویل: ستا دواړو زامنو څخه جوړ به شي دوه رقیب قومونه هغو دواړو کې به کشر وي قوي او مشر به وي غلام د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_23.mp3', '', 1761754199, 1761754199),
(38702, 'Genesis 25:24', 'Genesis', 25, 24, 'کله چې د هغې د اولاد د زېږولو وخت راورسېد، د هغې څخه غبرګوني پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_24.mp3', '', 1761754199, 1761754199),
(38703, 'Genesis 25:25', 'Genesis', 25, 25, 'لومړنی زوی چې پیدا شو، هغه سور ؤ او د هغه ټول بدن لکه د ببرې چپنې په شان ؤ، نو د هغه نوم یې عیسو کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_25.mp3', '', 1761754199, 1761754199),
(38704, 'Genesis 25:26', 'Genesis', 25, 26, 'د هغه څخه وروسته د هغه ورور پیدا شو او هغه د عیسو پونده په خپل لاس کې کلکه نیولې وه، نو ځکه د هغه نوم یعقوب شو. اسحاق د شپېتو کالو په عمر ؤ چې دوی پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_26.mp3', '', 1761754199, 1761754199),
(38705, 'Genesis 25:27', 'Genesis', 25, 27, 'هلکان لوی شول. عیسو یو تکړه ښکاري او داسې سړی ؤ چې صحرا یې خوښېدله، خو یعقوب یو ارام سړی ؤ او د کور څخه به نه وت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_27.mp3', '', 1761754199, 1761754199),
(38706, 'Genesis 25:28', 'Genesis', 25, 28, 'اسحاق د عیسو سره مینه کوله، ځکه چې هغه د هغو حیواناتو غوښه خوړله چې عیسو به ښکار کول. خو په ربکا باندې یعقوب ګران ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_28.mp3', '', 1761754199, 1761754199),
(38707, 'Genesis 25:29', 'Genesis', 25, 29, 'یوه ورځ یعقوب د قورمې په پخولو باندې بوخت ؤ. عیسو د ښکار څخه راغی او ډېر وږی ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_29.mp3', '', 1761754199, 1761754199),
(38708, 'Genesis 25:30', 'Genesis', 25, 30, 'او یعقوب ته یې وویل: «زه د لوږې له لاسه مړ کېږم، د دې لوبیا له قورمې څخه لږه راکړه!» (په دې خاطر یې په هغه باندې د ادوم نوم هم کېښود.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_30.mp3', '', 1761754199, 1761754199),
(38709, 'Genesis 25:31', 'Genesis', 25, 31, 'یعقوب ځواب ورکړ: «لومړی په ما باندې خپل د مشرتوب حق خرڅ کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_31.mp3', '', 1761754199, 1761754199),
(38710, 'Genesis 25:32', 'Genesis', 25, 32, 'عیسو وویل: «ګوره، زه مړ کېږم. دا مشرتوب ماته څه ګټه رسوي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis25_verse_32.mp3', '', 1761754199, 1761754199);